			Dpr.Box.BoxPokemonWork.UpdatePokemon(targetPokeParam, tray, pos);

		Dpr.BallDeco.BallDecoWork.RemoveAttachCapsule(tray, pos);
		IsGetMonsNo = ZukanWork.IsGet((uint)targetPokeParam.GetMonsNo());
		if (!targetPokeParam.IsEgg(EggCheckType.BOTH_EGG))
			ZukanWork.SetPoke(targetPokeParam, DPData.GET_STATUS.GET);
		targetPokeParam.Clear();

