		uint evolutionRoot = 0;
		PokemonParam poke = boxPokeData.teamIndex < 0
			? PlayerWork.playerParty.GetMemberPointer((uint)boxPokeData.teamPos)
			: Dpr.Box.BoxPokemonWork.GetPokemon(boxPokeData.teamIndex, boxPokeData.teamPos);
