				evolvePoke.Evolve(nextMonsNo, evolutionRoot);
				IsGetEvolvedMonsNo = ZukanWork.IsGet((uint)evolvePoke.GetMonsNo());
				ZukanWork.SetPoke(evolvePoke, DPData.GET_STATUS.GET);
				evolvedTargetPokeParam = new UnionTradeManager.BoxPokeData { pokeParam = evolvePoke, isTeam = true };
